1	package zkcircuit
2	
3	import (
4		"errors"
5		"fmt"
6		"strings"
7		"testing"
8	)
9	
10	// Regression tests for the compiled-artifact binding accepted on job
11	// submission. A non-empty CompiledHash belongs to exactly one circuit
12	// name+version (the artifact's), is matched as the exact string and is part
13	// of the job identity for idempotence/conflict checks. An empty hash keeps
14	// the register-only behavior forever: no auto-compile, no auto-binding.
15	//
16	// Every submission here uses a non-blank id, a positive attempt and kind
17	// "prove", so the observed failures are binding failures and not request
18	// validation noise.
19	
20	// compiledVersion creates a frozen version with a setup and a compiled
21	// artifact, returning that artifact's full hash.
22	func compiledVersion(t *testing.T, s *Store, name string, v int, def string) string {
23		t.Helper()
24		seedFrozenSource(t, s, name, v, 1, 1, 1, def)
25		a, err := s.GetArtifact(name, v)
26		if err != nil {
27			t.Fatalf("artifact for %q v%d: %v", name, v, err)
28		}
29		return a.Hash
30	}
31	
32	// frozenSetupUncompiled creates a frozen version with a setup but without a
33	// compiled artifact (a definition is imported, so it could be compiled
34	// later).
35	func frozenSetupUncompiled(t *testing.T, s *Store, name string, v int) {
36		t.Helper()
37		seedDraftWithDef(t, s, name, v, 1, 1, validDef)
38		if _, err := s.FreezeCircuit(name, v); err != nil {
39			t.Fatal(err)
40		}
41		if _, err := s.RecordSetup(name, v); err != nil {
42			t.Fatal(err)
43		}
44	}
45	
46	func boundProveJob(id, circuit string, version int, hash string) Job {
47		return Job{ID: id, Circuit: circuit, Version: version, Kind: "prove", Attempt: 1, CompiledHash: hash}
48	}
49	
50	// A successful binding stores the pinned version and the full hash; the
51	// submission result, GetJob and ListJobs agree, including after reopen.
52	func TestSubmitJobBoundHashRoundTrips(t *testing.T) {
53		dir := t.TempDir()
54		s, err := Open(dir)
55		if err != nil {
56			t.Fatal(err)
57		}
58		h := compiledVersion(t, s, "c", 1, validDef)
59	
60		submitted := boundProveJob("j-bound", "c", 1, h)
61		stored, err := s.SubmitJob(submitted)
62		if err != nil {
63			t.Fatalf("submit with own hash: %v", err)
64		}
65		if stored != submitted {
66			t.Fatalf("submit result differs from request:\n got %+v\nwant %+v", stored, submitted)
67		}
68		if stored.CompiledHash != h {
69			t.Fatalf("stored hash:\n got %q\nwant %q", stored.CompiledHash, h)
70		}
71	
72		got, err := s.GetJob("j-bound")
73		if err != nil {
74			t.Fatal(err)
75		}
76		if got != stored {
77			t.Fatalf("GetJob disagrees with submit result:\n got %+v\nwant %+v", got, stored)
78		}
79		jobs, err := s.ListJobs()
80		if err != nil {
81			t.Fatal(err)
82		}
83		if len(jobs) != 1 || jobs[0] != stored {
84			t.Fatalf("ListJobs disagrees with submit result: %+v", jobs)
85		}
86	
87		// The binding is committed state and survives a fresh process.
88		if err := s.Close(); err != nil {
89			t.Fatal(err)
90		}
91		s2, err := Open(dir)
92		if err != nil {
93			t.Fatalf("reopen: %v", err)
94		}
95		defer s2.Close()
96		got, err = s2.GetJob("j-bound")
97		if err != nil {
98			t.Fatal(err)
99		}
100		if got != stored {
101			t.Fatalf("binding lost on reopen:\n got %+v\nwant %+v", got, stored)
102		}
103		jobs, _ = s2.ListJobs()
104		if len(jobs) != 1 || jobs[0] != stored {
105			t.Fatalf("listed binding wrong after reopen: %+v", jobs)
106		}
107	}
108	
109	// Identical constraint definitions and identical input counts do not make
110	// hashes interchangeable: each name+version has its own artifact, and a
111	// foreign hash is an artifact mismatch against a new job id without touching
112	// any record.
113	func TestArtifactHashCannotBeBorrowedAcrossNameOrVersion(t *testing.T) {
114		s := openTestStore(t)
115		h1 := compiledVersion(t, s, "c", 1, validDef)
116		h2 := compiledVersion(t, s, "c", 2, validDef)
117		hOther := compiledVersion(t, s, "other", 1, validDef)
118	
119		// The identity (name and version) is folded into the hash even though the
120		// definitions and the 1/1/1 counts are byte-for-byte identical.
121		if h1 == h2 || h1 == hOther || h2 == hOther {
122			t.Fatalf("artifacts of different name/version share a hash: %q %q %q", h1, h2, hOther)
123		}
124	
125		cases := []struct {
126			name    string
127			circuit string
128			version int
129			hash    string
130		}{
131			{"same name other version borrows hash", "c", 1, h2},
132			{"other version borrows v1 hash", "c", 2, h1},
133			{"same version other name borrows hash", "other", 1, h1},
134			{"target borrows other-name hash", "c", 1, hOther},
135			{"unrelated foreign hash", "c", 1, "deadbeef"},
136		}
137		for i, tc := range cases {
138			t.Run(tc.name, func(t *testing.T) {
139				id := fmt.Sprintf("j-bad-%d", i)
140				before, err := readDataFile(t, s.Dir())
141				if err != nil {
142					t.Fatal(err)
143				}
144				if _, err := s.SubmitJob(boundProveJob(id, tc.circuit, tc.version, tc.hash)); !errors.Is(err, ErrArtifactMismatch) {
145					t.Fatalf("want artifact mismatch, got %v", err)
146				}
147				if _, err := s.GetJob(id); !errors.Is(err, ErrNotFound) {
148					t.Fatalf("rejected job %q left a record: %v", id, err)
149				}
150				jobs, _ := s.ListJobs()
151				if len(jobs) != 0 {
152					t.Fatalf("rejected binding stored a job: %+v", jobs)
153				}
154				after, err := readDataFile(t, s.Dir())
155				if err != nil {
156					t.Fatal(err)
157				}
158				if string(before) != string(after) {
159					t.Fatalf("rejected binding changed committed state")
160				}
161				// The version's own artifact is untouched.
162				if a, err := s.GetArtifact(tc.circuit, tc.version); err != nil || a.Hash == tc.hash {
163					t.Fatalf("artifact state wrong after mismatch: %+v err=%v", a, err)
164				}
165			})
166		}
167	
168		// Positive controls: each version binds only its own hash.
169		for i, target := range []struct {
170			id, name string
171			v        int
172			hash     string
173		}{
174			{"j1", "c", 1, h1}, {"j2", "c", 2, h2}, {"j3", "other", 1, hOther},
175		} {
176			if stored, err := s.SubmitJob(boundProveJob(target.id, target.name, target.v, target.hash)); err != nil {
177				t.Fatalf("own-hash submit #%d: %v", i, err)
178			} else if stored.CompiledHash != target.hash || stored.Version != target.v || stored.Circuit != target.name {
179				t.Fatalf("bound record wrong: %+v", stored)
180			}
181		}
182		jobs, _ := s.ListJobs()
183		if len(jobs) != 3 {
184			t.Fatalf("want 3 jobs, got %+v", jobs)
185		}
186	}
187	
188	// A non-empty hash against a target version without a compiled artifact is
189	// ErrArtifactMissing — whether the version merely has not been compiled yet
190	// or is a counts-only version that can never compile. Submission never
191	// triggers a compile, so the counts-only case must not surface
192	// ErrDefinitionMissing. Nothing is written.
193	func TestSubmitJobHashRequiresCompiledTarget(t *testing.T) {
194		s := openTestStore(t)
195		frozenSetupUncompiled(t, s, "defined", 1)
196		// Counts-only frozen version with a setup: register-only jobs stay legal,
197		// but it has no artifact.
198		readyCircuit(t, s, "bare", 1)
199	
200		cases := []struct {
201			name    string
202			circuit string
203		}{
204			{"defined but not yet compiled", "defined"},
205			{"counts only, no artifact possible", "bare"},
206		}
207		for _, tc := range cases {
208			t.Run(tc.name, func(t *testing.T) {
209				id := "j-missing-" + tc.circuit
210				before, err := readDataFile(t, s.Dir())
211				if err != nil {
212					t.Fatal(err)
213				}
214				if _, err := s.SubmitJob(boundProveJob(id, tc.circuit, 1, "some-hash")); !errors.Is(err, ErrArtifactMissing) {
215					t.Fatalf("want compiled artifact missing, got %v", err)
216				}
217				if _, err := s.GetJob(id); !errors.Is(err, ErrNotFound) {
218					t.Fatalf("refused job %q left a record: %v", id, err)
219				}
220				jobs, _ := s.ListJobs()
221				if len(jobs) != 0 {
222					t.Fatalf("refused submission stored a job: %+v", jobs)
223				}
224				after, err := readDataFile(t, s.Dir())
225				if err != nil {
226					t.Fatal(err)
227				}
228				if string(before) != string(after) {
229					t.Fatalf("rejected submission changed committed state")
230				}
231			})
232		}
233	}
234	
235	// The hash matches the exact submitted string: surrounding whitespace or
236	// changed letter case is a mismatch, never normalized into a match.
237	func TestSubmitJobHashMatchesExactly(t *testing.T) {
238		s := openTestStore(t)
239		h := compiledVersion(t, s, "c", 1, validDef)
240		upper := strings.ToUpper(h)
241		if upper == h {
242			t.Fatalf("test hash %q has no letters to flip the case of", h)
243		}
244		// Flip the first lowercase hex letter deterministically; the first
245		// character of a hex hash can be a digit, whose "case" is unchanged.
246		flipped := h
247		for i := 0; i < len(h); i++ {
248			if c := h[i]; c >= 'a' && c <= 'f' {
249				flipped = h[:i] + strings.ToUpper(h[i:i+1]) + h[i+1:]
250				break
251			}
252		}
253		if flipped == h {
254			t.Fatalf("test hash %q has no a-f letter to flip", h)
255		}
256	
257		variants := []struct {
258			name string
259			hash string
260		}{
261			{"leading space", " " + h},
262			{"trailing space", h + " "},
263			{"trailing tab", h + "\t"},
264			{"trailing newline", h + "\n"},
265			{"upper case", upper},
266			{"single letter case flip", flipped},
267		}
268		for i, tc := range variants {
269			t.Run(tc.name, func(t *testing.T) {
270				id := fmt.Sprintf("j-exact-%d", i)
271				if _, err := s.SubmitJob(boundProveJob(id, "c", 1, tc.hash)); !errors.Is(err, ErrArtifactMismatch) {
272					t.Fatalf("want artifact mismatch for %q, got %v", tc.name, err)
273				}
274				if _, err := s.GetJob(id); !errors.Is(err, ErrNotFound) {
275					t.Fatalf("normalized hash %q was accepted and stored", tc.name)
276				}
277			})
278		}
279		jobs, _ := s.ListJobs()
280		if len(jobs) != 0 {
281			t.Fatalf("exact-match failures left jobs: %+v", jobs)
282		}
283	
284		// The untouched exact string is the only accepted form.
285		stored, err := s.SubmitJob(boundProveJob("j-exact-ok", "c", 1, h))
286		if err != nil {
287			t.Fatalf("exact hash rejected: %v", err)
288		}
289		if stored.CompiledHash != h {
290			t.Fatalf("bound hash altered: got %q want %q", stored.CompiledHash, h)
291		}
292	}
293	
294	// The binding belongs to the job id. Identical resubmits are idempotent;
295	// changing or removing the hash, or adding one to a previously unbound job,
296	// is ErrConflict with the stored job preserved. The existing-id conflict is
297	// reported before the new request's artifact is validated.
298	func TestSubmitJobBindingConflictPreservesStoredJob(t *testing.T) {
299		cases := []struct {
300			name string
301			// run seeds a fresh store, submits the original job and returns it
302			// together with the conflicting resubmission.
303			run func(t *testing.T, s *Store) (original, conflict Job)
304		}{
305			{
306				name: "changed hash conflicts",
307				run: func(t *testing.T, s *Store) (Job, Job) {
308					h1 := compiledVersion(t, s, "c", 1, validDef)
309					h2 := compiledVersion(t, s, "c", 2, validDef)
310					original := boundProveJob("j", "c", 1, h1)
311					if _, err := s.SubmitJob(original); err != nil {
312						t.Fatal(err)
313					}
314					return original, boundProveJob("j", "c", 1, h2)
315				},
316			},
317			{
318				name: "removed hash conflicts",
319				run: func(t *testing.T, s *Store) (Job, Job) {
320					h1 := compiledVersion(t, s, "c", 1, validDef)
321					original := boundProveJob("j", "c", 1, h1)
322					if _, err := s.SubmitJob(original); err != nil {
323						t.Fatal(err)
324					}
325					return original, boundProveJob("j", "c", 1, "")
326				},
327			},
328			{
329				name: "adding hash to unbound job conflicts",
330				run: func(t *testing.T, s *Store) (Job, Job) {
331					h1 := compiledVersion(t, s, "c", 1, validDef)
332					original := boundProveJob("j", "c", 1, "")
333					if _, err := s.SubmitJob(original); err != nil {
334						t.Fatal(err)
335					}
336					return original, boundProveJob("j", "c", 1, h1)
337				},
338			},
339			{
340				name: "conflict precedes artifact mismatch",
341				run: func(t *testing.T, s *Store) (Job, Job) {
342					h1 := compiledVersion(t, s, "c", 1, validDef)
343					original := boundProveJob("j", "c", 1, h1)
344					if _, err := s.SubmitJob(original); err != nil {
345						t.Fatal(err)
346					}
347					// Sanity: for a fresh id this foreign hash is a real mismatch…
348					if _, err := s.SubmitJob(boundProveJob("fresh-id", "c", 1, "foreign-hash")); !errors.Is(err, ErrArtifactMismatch) {
349						t.Fatalf("sanity mismatch: %v", err)
350					}
351					// …but for the existing id the conflict is reported first.
352					return original, boundProveJob("j", "c", 1, "foreign-hash")
353				},
354			},
355			{
356				name: "conflict precedes artifact missing",
357				run: func(t *testing.T, s *Store) (Job, Job) {
358					h1 := compiledVersion(t, s, "c", 1, validDef)
359					// A frozen version with a setup but no artifact: a fresh id with
360					// any non-empty hash hits ErrArtifactMissing…
361					frozenSetupUncompiled(t, s, "d", 1)
362					original := boundProveJob("j", "c", 1, h1)
363					if _, err := s.SubmitJob(original); err != nil {
364						t.Fatal(err)
365					}
366					if _, err := s.SubmitJob(boundProveJob("fresh-id", "d", 1, "any-hash")); !errors.Is(err, ErrArtifactMissing) {
367						t.Fatalf("sanity missing: %v", err)
368					}
369					// …repurposing the existing id is a conflict first, not a new
370					// binding failure against "d" v1.
371					return original, boundProveJob("j", "d", 1, "any-hash")
372				},
373			},
374		}
375		for _, tc := range cases {
376			t.Run(tc.name, func(t *testing.T) {
377				s := openTestStore(t)
378				original, conflictReq := tc.run(t, s)
379	
380				if _, err := s.SubmitJob(conflictReq); !errors.Is(err, ErrConflict) {
381					t.Fatalf("want conflict, got %v", err)
382				}
383				got, err := s.GetJob("j")
384				if err != nil {
385					t.Fatal(err)
386				}
387				if got != original {
388					t.Fatalf("stored job changed after conflict:\n got %+v\nwant %+v", got, original)
389				}
390				jobs, _ := s.ListJobs()
391				// The sanity-check fresh ids were refused and stored nothing, so the
392				// conflict leaves exactly the original job.
393				if len(jobs) != 1 {
394					t.Fatalf("want exactly one job, got %+v", jobs)
395				}
396	
397				// The identical original request still returns the same record.
398				again, err := s.SubmitJob(original)
399				if err != nil || again != original {
400					t.Fatalf("identical resubmit after conflict: %+v %v", again, err)
401				}
402			})
403		}
404	}
405	
406	// An empty hash means unbound for the job's whole life: it is accepted on a
407	// not-yet-compiled version without compiling it, a later compilation never
408	// backfills the hash, an already-compiled target never auto-selects its
409	// artifact, counts-only versions keep their register-only ability, and no
410	// setup is auto-registered.
411	func TestEmptyHashLeavesJobUnbound(t *testing.T) {
412		t.Run("uncompiled version does not compile or bind", func(t *testing.T) {
413			dir := t.TempDir()
414			s, err := Open(dir)
415			if err != nil {
416				t.Fatal(err)
417			}
418			frozenSetupUncompiled(t, s, "c", 1)
419			req := boundProveJob("ju", "c", 1, "")
420			stored, err := s.SubmitJob(req)
421			if err != nil {
422				t.Fatalf("register-only submit: %v", err)
423			}
424			if stored != req || stored.CompiledHash != "" {
425				t.Fatalf("unbound job stored a binding: %+v", stored)
426			}
427			// Submission must not have compiled the version on the side.
428			if _, err := s.GetArtifact("c", 1); !errors.Is(err, ErrArtifactMissing) {
429				t.Fatalf("submit auto-compiled the version: %v", err)
430			}
431			// Compiling afterwards never backfills the old job's binding.
432			a, err := s.CompileCircuit("c", 1)
433			if err != nil {
434				t.Fatal(err)
435			}
436			got, _ := s.GetJob("ju")
437			if got.CompiledHash != "" {
438				t.Fatalf("later compilation backfilled the hash: %+v", got)
439			}
440			if err := s.Close(); err != nil {
441				t.Fatal(err)
442			}
443			s2, err := Open(dir)
444			if err != nil {
445				t.Fatal(err)
446			}
447			defer s2.Close()
448			got, _ = s2.GetJob("ju")
449			if got.CompiledHash != "" {
450				t.Fatalf("empty binding did not survive reopen: %+v", got)
451			}
452			if a2, err := s2.GetArtifact("c", 1); err != nil || a2.Hash != a.Hash {
453				t.Fatalf("compiled artifact state after reopen: %+v %v", a2, err)
454			}
455		})
456	
457		t.Run("compiled version does not auto-select artifact", func(t *testing.T) {
458			s := openTestStore(t)
459			h := compiledVersion(t, s, "c", 1, validDef)
460			stored, err := s.SubmitJob(boundProveJob("ju", "c", 1, ""))
461			if err != nil {
462				t.Fatalf("unbound submit against compiled version: %v", err)
463			}
464			if stored.CompiledHash != "" {
465				t.Fatalf("empty hash auto-bound to %q", stored.CompiledHash)
466			}
467			got, _ := s.GetJob("ju")
468			if got.CompiledHash != "" {
469				t.Fatalf("queried unbound job carries the artifact hash: %+v", got)
470			}
471			// A sibling explicit binding on the same version still works and stays
472			// distinct.
473			bound, err := s.SubmitJob(boundProveJob("jb", "c", 1, h))
474			if err != nil {
475				t.Fatal(err)
476			}
477			if bound.CompiledHash != h {
478				t.Fatalf("explicit binding wrong: %+v", bound)
479			}
480			jobs, _ := s.ListJobs()
481			if len(jobs) != 2 {
482				t.Fatalf("want 2 jobs, got %+v", jobs)
483			}
484			for _, j := range jobs {
485				want := h
486				if j.ID == "ju" {
487					want = ""
488				}
489				if j.CompiledHash != want {
490					t.Fatalf("job %q hash = %q, want %q", j.ID, j.CompiledHash, want)
491				}
492			}
493		})
494	
495		t.Run("counts-only version keeps register-only ability", func(t *testing.T) {
496			s := openTestStore(t)
497			readyCircuit(t, s, "bare", 1)
498			stored, err := s.SubmitJob(boundProveJob("jb", "bare", 1, ""))
499			if err != nil {
500				t.Fatalf("counts-only register-only submit: %v", err)
501			}
502			if stored.CompiledHash != "" {
503				t.Fatalf("counts-only job carries a hash: %+v", stored)
504			}
505			// This version can never compile (no definition imported); the job
506			// remains valid and unbound.
507			if _, err := s.CompileCircuit("bare", 1); !errors.Is(err, ErrDefinitionMissing) {
508				t.Fatalf("want definition missing, got %v", err)
509			}
510			got, err := s.GetJob("jb")
511			if err != nil || got != stored {
512				t.Fatalf("counts-only job after failed compile: %+v %v", got, err)
513			}
514		})
515	
516		t.Run("missing setup is not auto-registered even with empty hash", func(t *testing.T) {
517			s := openTestStore(t)
518			// Frozen and compiled, but deliberately no trusted setup.
519			seedDraftWithDef(t, s, "ns", 1, 1, 1, validDef)
520			if _, err := s.FreezeCircuit("ns", 1); err != nil {
521				t.Fatal(err)
522			}
523			if _, err := s.CompileCircuit("ns", 1); err != nil {
524				t.Fatal(err)
525			}
526			if _, err := s.SubmitJob(boundProveJob("jx", "ns", 1, "")); !errors.Is(err, ErrSetupMissing) {
527				t.Fatalf("want trusted setup missing, got %v", err)
528			}
529			if _, found, err := s.GetSetup("ns", 1); err != nil || found {
530				t.Fatalf("submit auto-registered a setup: found=%v err=%v", found, err)
531			}
532			if _, err := s.GetJob("jx"); !errors.Is(err, ErrNotFound) {
533				t.Fatalf("refused job left a record: %v", err)
534			}
535		})
536	}
