364	// Strict decoding of committed circuit records.
365	//
366	// A circuit record in data.json must name each of name, version, constraints,
367	// public_inputs, private_inputs, frozen and description exactly once, with
368	// the exact JSON type the writer emits (string / integer / integer / integer
369	// / integer / boolean / string). A missing key, a null, a wrong type or a
370	// repeated key is data corruption and refuses the whole directory read: a
371	// missing or null frozen flag must not silently read as false (turning a
372	// frozen version back into an editable draft), and a repeated key must not
373	// resolve to its last value. An explicit 0, false or "" is an ordinary value
374	// and stays legal. The definition member remains the one optional field: it
375	// may be absent or null (the legacy counts-only state); when present it goes
376	// through the strict persistDefinition decoder.
377	//
378	// Only shape is judged here. The domain rules (non-blank name, positive
379	// version and constraint count, non-negative input counts) keep being
380	// re-checked by validateEnvelope.
381	
382	var persistCircuitFields = []string{
383		"name", "version", "constraints", "public_inputs", "private_inputs",
384		"frozen", "description", "definition",
385	}
386	
387	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
388	// tagged for committed data: every structural failure in a stored circuit
389	// record is data corruption, never a bad request.
390	var storedRecordShape = jsonShape{fail: corruptf}
391	
392	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
393		const what = "stored circuit record"
394		if string(bytes.TrimSpace(raw)) == "null" {
395			return corruptf("%s must be a JSON object, not null", what)
396		}
397		members, err := strictCircuitObject(raw, what)
398		if err != nil {
399			return err
400		}
401	
402		var out persistCircuit
403	
404		requireString := func(key string, dst *string) error {
405			r, err := storedRecordShape.require(members, key, what)
406			if err != nil {
407				return err
408			}
409			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
410			if err != nil {
411				return err
412			}
413			*dst = v
414			return nil
415		}
416		requireInt := func(key string, dst *int) error {
417			r, err := storedRecordShape.require(members, key, what)
418			if err != nil {
419				return err
420			}
421			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
422			if err != nil {
423				return err
424			}
425			*dst = v
426			return nil
427		}
428	
429		if err := requireString("name", &out.Name); err != nil {
430			return err
431		}
432		if err := requireInt("version", &out.Version); err != nil {
433			return err
434		}
435		if err := requireInt("constraints", &out.Constraints); err != nil {
436			return err
437		}
438		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
439			return err
440		}
441		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
442			return err
443		}
444		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
445		if err != nil {
446			return err
447		}
448		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
449		if err != nil {
450			return err
451		}
452		if err := requireString("description", &out.Description); err != nil {
453			return err
454		}
455	
456		// definition is the only optional member: absent or null both mean the
457		// counts-only legacy state.
458		if defRaw, present := members["definition"]; present {
459			if string(bytes.TrimSpace(defRaw)) != "null" {
460				var def persistDefinition
461				if err := json.Unmarshal(defRaw, &def); err != nil {
462					var se StoreError
463					if errors.As(err, &se) {
464						return err // already reported as data corruption
465					}
466					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
467				}
468				out.Definition = &def
469			}
470		}
471	
472		*c = out
473		return nil
474	}
