556	// compiledHashKey is the canonical spelling of a job record's
557	// compiled-artifact binding field.
558	const compiledHashKey = "compiled_hash"
559	
560	// isCompiledHashKey reports whether key names the compiled-artifact binding
561	// field, allowing differences in ASCII letter case only: "compiled_hash",
562	// "COMPILED_HASH" and every mixed-case spelling are the same field. Keys are
563	// already JSON-unescaped at this point, so an escaped spelling of any of
564	// these forms lands here too. Non-ASCII lookalikes never match.
565	func isCompiledHashKey(key string) bool {
566		if len(key) != len(compiledHashKey) {
567			return false
568		}
569		for i := 0; i < len(key); i++ {
570			c := key[i]
571			if c >= 'A' && c <= 'Z' {
572				c += 'a' - 'A'
573			}
574			if c != compiledHashKey[i] {
575				return false
576			}
577		}
578		return true
579	}
