581	// Strict decoding of the compiled-artifact binding on a committed job record.
582	//
583	// compiled_hash is a field whose presence is meaningful: records written
584	// before bindings existed simply omit it, and an explicit "" is the unbound
585	// state. But once the key appears its value must be a JSON string. A null is
586	// not "no binding" — it is damage to a binding the record claims to carry,
587	// and so is a number, boolean, array or object in its place. Reading either
588	// as the zero string would silently turn a bound job into an unbound one
589	// (and the next commit would drop the field entirely), so the read is
590	// refused as data corruption instead. A repeated key — including one
591	// repeated through JSON string escapes, even with identical values — is
592	// likewise refused rather than resolved to its last value. A legal non-empty
593	// string keeps being matched against the pinned version's artifact by
594	// validateEnvelope, exactly as written.
595	//
596	// The field is recognized under any ASCII letter-case spelling, so a record
597	// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
598	// same binding and follows the same rules: a single such key is read with
599	// the full string validation above, and two spellings of the field on one
600	// record — even with byte-identical values — are a duplicate binding and
601	// corrupt the read rather than being resolved by key order.
602	//
603	// Only the binding field is judged here; every other field keeps the
604	// ordinary struct decoding.
605	func (j *persistJob) UnmarshalJSON(raw []byte) error {
606		const what = "stored job record"
607		if string(bytes.TrimSpace(raw)) == "null" {
608			return corruptf("%s must be a JSON object, not null", what)
609		}
610		members, err := strictObjectMembers(raw, what, nil)
611		if err != nil {
612			return err
613		}
614		// Name the job in a binding-field failure when its id is legible; the id
615		// itself is decoded for real by the ordinary pass below.
616		where := what
617		if idRaw, ok := members["id"]; ok {
618			if id, idErr := storedRecordShape.string(idRaw, what+` field "id"`); idErr == nil {
619				where = fmt.Sprintf("stored job record %q", id)
620			}
621		}
622		// Every spelling of the binding field counts as the same one field; the
623		// record may carry it at most once, however it is capitalized.
624		var bindingKeys []string
625		for key := range members {
626			if isCompiledHashKey(key) {
627				bindingKeys = append(bindingKeys, key)
628			}
629		}
630		if len(bindingKeys) > 1 {
631			sort.Strings(bindingKeys)
632			quoted := make([]string, len(bindingKeys))
633			for i, k := range bindingKeys {
634				quoted[i] = strconv.Quote(k)
635			}
636			return corruptf("%s carries the binding field %q more than once (as %s)",
637				where, compiledHashKey, strings.Join(quoted, ", "))
638		}
639		compiledHash := ""
640		hasBinding := false
641		if len(bindingKeys) == 1 {
642			hash, err := storedRecordShape.string(members[bindingKeys[0]], where+` field "compiled_hash"`)
643			if err != nil {
644				return err
645			}
646			compiledHash, hasBinding = hash, true
647		}
648		type plainJob persistJob
649		var decoded plainJob
650		if err := json.Unmarshal(raw, &decoded); err != nil {
651			return corruptf("%s is not valid JSON: %v", what, err)
652		}
653		if hasBinding {
654			decoded.CompiledHash = compiledHash
655		}
656		*j = persistJob(decoded)
657		return nil
658	}
