660	// Store is a persistent workbench backed by one local data directory.
661	//
662	// All operations are safe for concurrent use by multiple goroutines and by
663	// several processes pointed at the same directory: an in-process mutex plus a
664	// process-shared flock serialize commits, and every commit is an atomic
665	// temp-file/fsync/rename replacement. Open the directory with Open and call
666	// Close when done.
667	type Store struct {
668		dir  string
669		mu   sync.Mutex
670		lock *os.File
671	
672		data envelope
673	}
674	
675	// Open opens (creating if needed) the workbench data in dir. If the
676	// directory does not exist it is created. Existing committed data is loaded
677	// and fully validated before Open returns; on a corrupt, truncated or
678	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
679	// leaves every file in the directory untouched.
680	func Open(dir string) (*Store, error) {
681		if dir == "" {
682			return nil, invalidf("data directory must not be empty")
683		}
684		if err := os.MkdirAll(dir, 0o755); err != nil {
685			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
686		}
687		lockPath := filepath.Join(dir, dirLockFile)
688		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
689		if err != nil {
690			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
691		}
692		// Serialize against other processes while we read / validate.
693		if err := lockExclusive(lock); err != nil {
694			lock.Close()
695			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
696		}
697	
698		s := &Store{dir: dir, lock: lock}
699		if err := s.loadLocked(); err != nil {
700			unlockLock(lock)
701			lock.Close()
702			return nil, err
703		}
704		// The lock is taken again per operation; holding it for the store's
705		// lifetime would forbid two open handles on one directory.
706		if err := unlockLock(lock); err != nil {
707			lock.Close()
708			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
709		}
710		return s, nil
711	}
712	
713	// Close releases the directory lock. It does not discard committed data.
714	func (s *Store) Close() error {
715		s.mu.Lock()
716		defer s.mu.Unlock()
717		if s.lock == nil {
718			return nil
719		}
720		var first error
721		if err := unlockLock(s.lock); err != nil {
722			first = err
723		}
724		if err := s.lock.Close(); err != nil && first == nil {
725			first = err
726		}
727		s.lock = nil
728		return first
729	}
730	
731	// Dir reports the data directory backing the store.
732	func (s *Store) Dir() string { return s.dir }
733	
734	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
735	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
736	
737	// loadLocked reads and validates the committed file. Caller must hold the
738	// exclusive flock; the in-process mutex is taken by the public Open path.
739	func (s *Store) loadLocked() error {
740		raw, err := os.ReadFile(s.dataPath())
741		if errors.Is(err, os.ErrNotExist) {
742			s.data = envelope{Format: FormatVersion}
743			return nil
744		}
745		if err != nil {
746			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
747		}
748		if len(strings.TrimSpace(string(raw))) == 0 {
749			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
750		}
751	
752		var env envelope
753		if err := json.Unmarshal(raw, &env); err != nil {
754			// Shape failures surfaced by the persisted-definition decoders are
755			// integrity failures, not JSON syntax errors; report their detail
756			// instead of the generic "not valid JSON" wording.
757			var se StoreError
758			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
759				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
760			}
761			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
762		}
763		if env.Format == 0 {
764			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
765		}
766		if env.Format != FormatVersion {
767			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
768				s.dataPath(), env.Format, FormatVersion)
769		}
770		if err := validateEnvelope(env); err != nil {
771			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
772		}
773		s.data = env
774		return nil
775	}
776	
777	// commitLocked writes the pending state atomically: temp file → fsync →
778	// rename → fsync directory. Caller must hold both the in-process mutex and
779	// the exclusive flock; all in-memory mutations must already have happened and
780	// been rule-checked, so a failure here occurs before any success is reported.
781	func (s *Store) commitLocked() error {
782		s.data.Format = FormatVersion
783		// Stable output: records are stored sorted so files are deterministic.
784		sortEnvelope(&s.data)
785	
786		payload, err := json.MarshalIndent(&s.data, "", "  ")
787		if err != nil {
788			return fmt.Errorf("cannot encode data: %w", err)
789		}
790		payload = append(payload, '\n')
791	
792		tmp := s.tmpPath()
793		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
794		if err != nil {
795			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
796		}
797		if _, err := f.Write(payload); err != nil {
798			f.Close()
799			os.Remove(tmp)
800			return fmt.Errorf("cannot write staged data: %w", err)
801		}
802		if err := f.Sync(); err != nil {
803			f.Close()
804			os.Remove(tmp)
805			return fmt.Errorf("cannot flush staged data: %w", err)
806		}
807		if err := f.Close(); err != nil {
808			os.Remove(tmp)
809			return fmt.Errorf("cannot finish staged data: %w", err)
810		}
811		if err := os.Rename(tmp, s.dataPath()); err != nil {
812			os.Remove(tmp)
813			return fmt.Errorf("cannot commit data file: %w", err)
814		}
815		if err := syncDir(s.dir); err != nil {
816			// The rename already happened; lack of dir fsync only weakens crash
817			// durability, never correctness of what is visible now.
818			return nil
819		}
820		return nil
821	}
822	
823	// withLock runs fn under the in-process mutex and an exclusive flock, then
824	// atomically commits when fn requests it. The on-disk state is re-read after
825	// acquiring the lock, so concurrent commits from another process or another
826	// handle are always observed. Operations validate before mutating; a rejected
827	// operation (commit=false or an error) writes nothing and leaves committed
828	// state unchanged.
829	func (s *Store) withLock(fn func() (commit bool, err error)) error {
830		s.mu.Lock()
831		defer s.mu.Unlock()
832		if s.lock == nil {
833			return invalidf("store is closed")
834		}
835		if err := lockExclusive(s.lock); err != nil {
836			return fmt.Errorf("cannot lock data directory: %w", err)
837		}
838		defer unlockLock(s.lock)
839	
840		if err := s.loadLocked(); err != nil {
841			return err
842		}
843		commit, err := fn()
844		if err != nil {
845			return err
846		}
847		if !commit {
848			return nil
849		}
850		return s.commitLocked()
851	}
852	
853	// withLockRead runs fn under a shared flock over freshly reloaded state.
854	func (s *Store) withLockRead(fn func() error) error {
855		s.mu.Lock()
856		defer s.mu.Unlock()
857		if s.lock == nil {
858			return invalidf("store is closed")
859		}
860		if err := lockShared(s.lock); err != nil {
861			return fmt.Errorf("cannot lock data directory: %w", err)
862		}
863		defer unlockLock(s.lock)
864		if err := s.loadLocked(); err != nil {
865			return err
866		}
867		return fn()
868	}
869	
870	func sortEnvelope(env *envelope) {
871		sort.Slice(env.Circuits, func(i, j int) bool {
872			if env.Circuits[i].Name != env.Circuits[j].Name {
873				return env.Circuits[i].Name < env.Circuits[j].Name
874			}
875			return env.Circuits[i].Version < env.Circuits[j].Version
876		})
877		sort.Slice(env.Setups, func(i, j int) bool {
878			if env.Setups[i].Name != env.Setups[j].Name {
879				return env.Setups[i].Name < env.Setups[j].Name
880			}
881			return env.Setups[i].Version < env.Setups[j].Version
882		})
883		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
884		sort.Slice(env.Artifacts, func(i, j int) bool {
885			if env.Artifacts[i].Name != env.Artifacts[j].Name {
886				return env.Artifacts[i].Name < env.Artifacts[j].Name
887			}
888			return env.Artifacts[i].Version < env.Artifacts[j].Version
889		})
890	}
891	
892	// validateEnvelope re-checks every invariant on load so a tampered or
893	// hand-edited file cannot bypass the domain rules.
894	func validateEnvelope(env envelope) error {
895		seenCircuit := make(map[[2]string]bool)
896		circuitOK := make(map[[2]string]bool)
897		for i, c := range env.Circuits {
898			key := [2]string{c.Name, itoa(c.Version)}
899			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
900				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
901			}
902			if c.Version <= 0 {
903				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
904			}
905			if seenCircuit[key] {
906				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
907			}
908			seenCircuit[key] = true
909			if c.Constraints <= 0 {
910				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
911			}
912			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
913				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
914			}
915			// The same representability rule the write path enforces: wire 0 plus
916			// every declared input must fit inside the platform's int. A record
917			// beyond that bound can never have been written by this build and
918			// cannot be checked safely, so the directory is corrupt rather than
919			// silently narrowed or read with a wrapped-around layout.
920			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
921				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
922					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
923			}
924			if c.Definition != nil {
925				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
926					return err
927				}
928			}
929			circuitOK[key] = true
930		}
931		seenSetup := make(map[[2]string]bool)
932		for i, p := range env.Setups {
933			key := [2]string{p.Name, itoa(p.Version)}
934			if !circuitOK[key] {
935				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
936			}
937			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
938			if c == nil || !c.Frozen {
939				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
940			}
941			if seenSetup[key] {
942				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
943			}
944			seenSetup[key] = true
945		}
946		seenJob := make(map[string]bool)
947		for i, j := range env.Jobs {
948			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
949				return fmt.Errorf("job #%d has an empty or blank id", i+1)
950			}
951			if seenJob[j.ID] {
952				return fmt.Errorf("job %q appears more than once", j.ID)
953			}
954			seenJob[j.ID] = true
955			if j.Kind != "prove" {
956				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
957			}
958			if j.Attempt <= 0 {
959				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
960			}
961			key := [2]string{j.Circuit, itoa(j.Version)}
962			if !circuitOK[key] {
963				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
964			}
965			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
966			if c == nil || !c.Frozen {
967				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
968			}
969			if !seenSetup[key] {
970				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
971			}
972			// A recorded compiled-artifact binding must still resolve against the
973			// pinned version's artifact; a dangling or mismatched binding makes
974			// the file unreadable rather than silently dropping the binding.
975			if j.CompiledHash != "" {
976				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
977				if artifact == nil {
978					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
979				}
980				if artifact.Hash != j.CompiledHash {
981					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
982						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
983				}
984			}
985		}
986		seenArtifact := make(map[[2]string]bool)
987		for i, a := range env.Artifacts {
988			key := [2]string{a.Name, itoa(a.Version)}
989			if !circuitOK[key] {
990				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
991			}
992			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
993			if c == nil || !c.Frozen {
994				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
995			}
996			if seenArtifact[key] {
997				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
998			}
999			seenArtifact[key] = true
1000			if c.Definition == nil {
1001				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1002			}
1003			if a.Constraints != c.Constraints {
1004				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1005					a.Name, a.Version, a.Constraints, c.Constraints)
1006			}
1007			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1008			if err != nil {
1009				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1010			}
1011			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1012				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1013			}
1014			wantHash := artifactHash(a.Name, a.Version, def)
1015			if a.Hash != wantHash {
1016				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1017					a.Name, a.Version, a.Hash, wantHash)
1018			}
1019		}
1020		return nil
1021	}
1022	
1023	// validatePersistDefinition re-validates a stored definition against its
1024	// version's declared counts: prime modulus, in-range wires and an exact
1025	// constraint count match.
1026	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1027		parsed, err := definitionFromPersist(*def, public, private)
1028		if err != nil {
1029			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1030		}
1031		if !parsed.compatibleWith(constraints, public, private) {
1032			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1033		}
1034		return nil
1035	}
1036	
1037	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1038		for i := range cs {
1039			if cs[i].Name == name && cs[i].Version == version {
1040				return &cs[i]
1041			}
1042		}
1043		return nil
1044	}
1045	
1046	func itoa(v int) string { return fmt.Sprintf("%d", v) }
