// these forms lands here too. Non-ASCII lookalikes never match.
func isCompiledHashKey(key string) bool {
	if len(key) != len(compiledHashKey) {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		if c >= 'A' && c <= 'Z' {
